"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract checks every member before it writes anything, so an archive it refuses leaves
the destination as it was.

The check doesn't trust a member's name alone: a link the archive made earlier (or one already in the destination)
can send a later name, or another link's target, somewhere the name doesn't show. So the plan replays the archive on
a model of the destination, resolving every path the way the kernel will once the earlier members exist, and each
member is then written to the real folder its path resolves to.
"""
import os
import shutil
import stat
import tarfile

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755
MAX_LINK_HOPS = 40  # Linux gives up (ELOOP) after 40 links; we refuse at the same depth rather than guess past it

DIR, FILE, LINK = "dir", "file", "link"


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted, and a link may point only inside dest. A member that
    would land outside dest, a link that points outside it, a name listed twice, any other kind of member or an
    archive over the size limits raises UnsafeArchive, and then nothing has been written."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    with tarfile.open(tar_path) as tar:
        members = tar.getmembers()
        limits.check(members)
        plan = plan_members(root, members)
        for member, target in plan:
            write_member(tar, member, target)
    return [paths.clean_name(m.name) for m in members]


class _Tree:
    """The destination as it will be after the members planned so far: what the archive adds, over what's on disk."""

    def __init__(self, root):
        self.root = root
        self.added = {}  # (part, ...) relative to root -> (DIR,) | (FILE,) | (LINK, linkname)

    def kind(self, parts):
        """(DIR,), (FILE,), (LINK, target) or None for the entry at parts; never follows a link at parts itself."""
        if parts in self.added:
            return self.added[parts]
        try:
            st = os.lstat(os.path.join(self.root, *parts))
        except (FileNotFoundError, NotADirectoryError):
            return None
        if stat.S_ISLNK(st.st_mode):
            return (LINK, os.readlink(os.path.join(self.root, *parts)))
        return (DIR,) if stat.S_ISDIR(st.st_mode) else (FILE,)  # anything else on disk is no folder either

    def _expand(self, cur, linkname, where):
        """(parts to start from, parts still to walk) for following a link found at cur + [name] to linkname."""
        if "\x00" in linkname or not linkname:
            raise UnsafeArchive(f"{where} goes through a link with a bad target")
        if linkname.startswith("/"):
            # Only a link already on disk can be absolute (the archive's are refused); follow it if it stays inside.
            target = os.path.normpath(linkname)
            if not paths.is_within(self.root, target):
                raise UnsafeArchive(f"{where} goes through a link to {linkname}, outside the destination")
            return [], [p for p in target[len(self.root):].split("/") if p]
        return list(cur), linkname.split("/")

    def resolve(self, start, parts, mode, where, hops):
        """The parts, relative to root and with no links left in them, that start + parts leads to; UnsafeArchive
        if the walk would leave root at any step.

        mode "strict": every step must exist, as the kernel needs to follow a link to a folder.
        mode "create": the walk os.makedirs does for a member's parent: missing plain steps will be made as folders,
            but a link on the way must lead to a folder that exists (or makedirs fails).
        mode "lenient": how a link's target reads later; missing steps are taken as they're spelled.
        The last step is followed too if it's a link."""
        cur, todo = list(start), list(parts)
        while todo:
            part = todo.pop(0)
            if part in ("", "."):
                continue
            if part == "..":
                if not cur:
                    raise UnsafeArchive(f"{where} leads outside the destination")
                cur.pop()
                continue
            found = self.kind(tuple(cur + [part]))
            if found is not None and found[0] == LINK:
                hops[0] += 1
                if hops[0] > MAX_LINK_HOPS:
                    raise UnsafeArchive(f"{where} goes through more than {MAX_LINK_HOPS} links")
                base, rest = self._expand(cur, found[1], where)
                if mode == "create":
                    cur = self.resolve(base, rest, "strict", where, hops)
                    if self.kind(tuple(cur)) != (DIR,) and cur:
                        raise UnsafeArchive(f"{where} goes through a link that isn't to a folder")
                else:
                    cur, todo = base, rest + todo
                continue
            if found is None and mode == "strict":
                raise UnsafeArchive(f"{where} goes through a link to something that doesn't exist")
            if found is not None and found[0] != DIR and (mode == "create" or (todo and mode == "strict")):
                raise UnsafeArchive(f"{where} goes through {'/'.join(cur + [part])}, which isn't a folder")
            cur.append(part)
        return cur

    def add(self, parts, entry):
        for i in range(1, len(parts)):  # the parent folders makedirs will make
            if self.kind(parts[:i]) is None:
                self.added[parts[:i]] = (DIR,)
        self.added[parts] = entry


def plan_members(root, members):
    """[(member, the absolute path it goes to), ...] once every member has passed, or UnsafeArchive."""
    tree = _Tree(root)
    seen = set()
    plan = []
    links = []
    for member in members:
        name = paths.clean_name(member.name)
        if name in seen:
            raise UnsafeArchive(f"{name} is listed twice")
        seen.add(name)
        target = paths.under(root, name)
        if not paths.is_within(root, os.path.realpath(target)):
            raise UnsafeArchive(f"{name} would be written outside the destination")
        if member.issym():
            if not member.linkname or os.path.isabs(member.linkname):
                raise UnsafeArchive(f"{name} links to an absolute path")
            if "\x00" in member.linkname:
                raise UnsafeArchive(f"{name} has a bad link target")
            if not paths.is_within(root, paths.link_target(root, name, member.linkname)):
                raise UnsafeArchive(f"{name} links to {member.linkname}, outside the destination")
        elif member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        elif not (member.isfile() or member.isdir()):
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")

        # Where the member really lands, once the links before it exist.
        parts = name.split("/")
        hops = [0]
        place = tree.resolve([], parts[:-1], "create", name, hops) + [parts[-1]]
        there = tree.kind(tuple(place))
        if member.isdir():
            if there is not None and there[0] == LINK:
                place = tree.resolve(place[:-1], place[-1:], "strict", name, hops)
                there = tree.kind(tuple(place))
            if there is not None and there != (DIR,):
                raise UnsafeArchive(f"{name} is a folder where the archive or the destination has something else")
            if place:
                tree.add(tuple(place), (DIR,))
        else:
            if there is not None:
                raise UnsafeArchive(f"{name} would overwrite something already there")
            if member.issym():
                tree.add(tuple(place), (LINK, member.linkname))
                links.append((name, place, member.linkname))
            else:
                tree.add(tuple(place), (FILE,))
        plan.append((member, os.path.join(root, *place)))

    # Every link must lead inside root in the finished tree, through whatever links come before or after it.
    for name, place, linkname in links:
        tree.resolve(place[:-1], linkname.split("/"), "lenient", f"{name} -> {linkname}", [0])
    return plan


def write_member(tar, member, target):
    """target is the real path planned for member: no link on the way to it, nothing at it but a folder."""
    if member.isdir():
        os.makedirs(target, exist_ok=True)
        return
    os.makedirs(os.path.dirname(target), exist_ok=True)
    if member.issym():
        os.symlink(member.linkname, target)
        return
    mode = EXEC_MODE if member.mode & 0o100 else FILE_MODE
    fd = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), mode)
    with tar.extractfile(member) as src, open(fd, "wb") as out:
        os.fchmod(out.fileno(), mode)
        shutil.copyfileobj(src, out)

