"""MANIFEST.json, written at the root of every backup: the sha256 of each file and the target of each link."""
import hashlib
import json
import os

from archive.errors import UnsafeArchive
from archive.pack import walk
from archive.paths import clean_name, is_within

NAME = "MANIFEST.json"


class ManifestMismatch(ValueError):
    pass


def sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as f:
        for block in iter(lambda: f.read(1 << 16), b""):
            digest.update(block)
    return digest.hexdigest()


def build(root):
    """{"files": {path: sha256}, "links": {path: target}} for the tree under root, paths relative and POSIX."""
    files, links = {}, {}
    for rel, path in walk(root):
        if rel == NAME:
            continue
        if os.path.islink(path):
            links[rel] = os.readlink(path)
        elif os.path.isfile(path):
            files[rel] = sha256(path)
    return {"files": files, "links": links}


def dumps(manifest):
    return json.dumps(manifest, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def _listed(manifest, key):
    entries = manifest.get(key, {}) if isinstance(manifest, dict) else None
    if not isinstance(entries, dict) or not all(isinstance(v, str) for v in entries.values()):
        raise ManifestMismatch(f"the manifest's {key!r} isn't a map of paths to strings")
    return entries.items()


def _inside(root, rel, follow_last):
    """The path rel names under root. ManifestMismatch unless rel is a clean relative path that stays inside root:
    the manifest comes from the uploaded tar, so it must not get us to read (and so checksum) files outside."""
    try:
        clean = clean_name(rel)
    except UnsafeArchive:
        raise ManifestMismatch(f"the manifest lists a bad path {rel!r}") from None
    real_root = os.path.realpath(root)
    path = os.path.join(real_root, *clean.split("/"))
    check = os.path.realpath(path if follow_last else os.path.dirname(path))
    if not is_within(real_root, check):
        raise ManifestMismatch(f"{rel} is outside the backup")
    return path


def verify(root, manifest):
    """ManifestMismatch unless every file and link the manifest lists is under root as it says."""
    for rel, digest in _listed(manifest, "files"):
        path = _inside(root, rel, follow_last=True)
        if os.path.islink(path) or not os.path.isfile(path):
            raise ManifestMismatch(f"{rel} is missing")
        if sha256(path) != digest:
            raise ManifestMismatch(f"{rel} doesn't match its checksum")
    for rel, target in _listed(manifest, "links"):
        path = _inside(root, rel, follow_last=False)
        if not os.path.islink(path) or os.readlink(path) != target:
            raise ManifestMismatch(f"{rel} should link to {target}")

