"""Migrate a v2 export to the v3 format.

migrate(src, accounts, dst) reads the v2 export at src (docs/FORMAT_V2.md) and the accounts file at accounts
(data/accounts.json shows the shape), writes the v3 file at dst (docs/FORMAT_V3.md, "Migrating from v2") and
returns the number of records written.

The export can be far larger than memory, so it is streamed and both steps that need an ordering (picking each
entry's current revision, then sorting by account, posted_at, id) are external merge sorts over temporary files
kept next to dst. Only the accounts lookup and one sort chunk are held in memory at a time. Every line is checked
before anything is written; dst is only created, atomically, once the whole migration has succeeded.
"""
import heapq
import json
import os
import tempfile

from . import accounts as accounts_file
from . import kinds, money, timefmt, v2, v3
from .errors import FormatError, MigrationError

CHUNK = 200_000  # items sorted in memory at once
FAN_IN = 64  # temporary files merged at once


def _convert(record, number, held):
    """A checked v2 record as its v3 record. MigrationError naming the line when it can't be migrated."""
    try:
        v2.check(record, number)
    except FormatError as e:
        raise MigrationError(str(e)) from None

    account = held.get(record["account"])
    if account is None:
        raise MigrationError(f"account {record['account']!r} isn't in the accounts file", number)

    kind = record["kind"]
    entry_type = kind if kind in kinds.TYPES else kinds.LEGACY.get(kind)
    if entry_type is None:
        raise MigrationError(f"unknown kind {kind!r}", number)

    currency = record["currency"] if record["currency"] is not None else account.currency
    if not money.is_currency(currency):
        raise MigrationError(f"bad currency {currency!r}", number)

    amount = record["amount"]
    if amount.startswith("-"):
        raise MigrationError(f"amount {amount!r} must be positive; the kind gives the sign", number)
    try:
        minor = money.to_minor(amount, currency)
    except ValueError as e:
        raise MigrationError(str(e), number) from None

    try:
        stamp = timefmt.parse_ts(record["ts"])
    except ValueError as e:
        raise MigrationError(str(e), number) from None
    if stamp.tzinfo is None:  # the 2020 bulk importer: the account's local time
        stamp = stamp.replace(tzinfo=account.tz)
    posted_at = timefmt.to_utc_z(stamp)

    out = {"id": record["id"], "account": record["account"], "type": entry_type,
           "amount_minor": kinds.SIGN[entry_type] * minor, "currency": currency, "posted_at": posted_at,
           "memo": record["memo"], "source_rev": record["rev"]}
    try:
        line = v3.dump_line(out)
    except FormatError as e:
        raise MigrationError(str(e), number) from None
    return out, line


def _lines(src):
    """(line number, record) for every non-blank line, streamed."""
    with open(src, "rb") as f:
        for number, raw in enumerate(f, 1):
            if number == 1 and raw.startswith(b"\xef\xbb\xbf"):
                raw = raw[3:]
            try:
                text = raw.decode("utf-8")
            except UnicodeDecodeError as e:
                raise MigrationError(f"not UTF-8 ({e})", number) from None
            if not text.strip():
                continue
            try:
                record = json.loads(text)
            except ValueError as e:
                raise MigrationError(f"not JSON ({e})", number) from None
            yield number, record


class _Sorter:
    """An external sort of JSON-able lists, compared as lists, spilled to files in tmpdir."""

    def __init__(self, tmpdir):
        self.tmpdir = tmpdir
        self.buffer = []
        self.runs = []

    def add(self, item):
        self.buffer.append(item)
        if len(self.buffer) >= CHUNK:
            self._spill()

    def _new_file(self):
        fd, path = tempfile.mkstemp(dir=self.tmpdir, suffix=".run")
        return path, open(fd, "w", encoding="utf-8", newline="\n")

    def _spill(self):
        if not self.buffer:
            return
        self.buffer.sort()
        path, f = self._new_file()
        with f:
            for item in self.buffer:
                f.write(json.dumps(item, ensure_ascii=False, separators=(",", ":")) + "\n")
        self.buffer = []
        self.runs.append(path)

    @staticmethod
    def _read(path):
        with open(path, encoding="utf-8") as f:
            for text in f:
                yield json.loads(text)

    def _merge(self, paths):
        return heapq.merge(*(self._read(p) for p in paths))

    def sorted(self):
        """Every item added, in order. The runs are removed as they are consumed."""
        if not self.runs:  # everything fit in memory
            items, self.buffer = sorted(self.buffer), []
            yield from items
            return
        self._spill()
        while len(self.runs) > FAN_IN:
            batch, self.runs = self.runs[:FAN_IN], self.runs[FAN_IN:]
            path, f = self._new_file()
            with f:
                for item in self._merge(batch):
                    f.write(json.dumps(item, ensure_ascii=False, separators=(",", ":")) + "\n")
            for p in batch:
                os.remove(p)
            self.runs.append(path)
        yield from self._merge(self.runs)
        for p in self.runs:
            os.remove(p)
        self.runs = []


def migrate(src, accounts, dst):
    try:
        held = accounts_file.load(accounts)
    except FormatError as e:
        raise MigrationError(f"accounts file: {e}") from None

    dst = os.fspath(dst)
    workdir = os.path.dirname(os.path.abspath(dst))
    with tempfile.TemporaryDirectory(dir=workdir, prefix=".migrate_v3-") as tmp:
        # 1. Check and convert every line; sort by id, then rev, then position in the file.
        by_entry = _Sorter(tmp)
        for number, record in _lines(src):
            out, line = _convert(record, number, held)
            by_entry.add([out["id"], out["source_rev"], number,
                          out["account"], out["posted_at"], line])

        # 2. Keep each id's last item: its highest rev, the latest line among equal revs. Sort the survivors.
        by_output = _Sorter(tmp)
        current = None
        for item in by_entry.sorted():
            if current is not None and item[0] != current[0]:
                by_output.add([current[3], current[4], current[0], current[5]])
            current = item
        if current is not None:
            by_output.add([current[3], current[4], current[0], current[5]])

        # 3. Write them in account, posted_at, id order, then move the finished file into place.
        fd, part = tempfile.mkstemp(dir=workdir, prefix=".migrate_v3-", suffix=".part")
        count = 0
        try:
            with open(fd, "w", encoding="utf-8", newline="\n") as f:
                for item in by_output.sorted():
                    f.write(item[3])
                    count += 1
            umask = os.umask(0)
            os.umask(umask)
            os.chmod(part, 0o666 & ~umask)  # mkstemp makes it private; give it a normal file's mode
            os.replace(part, dst)
        except BaseException:
            if os.path.exists(part):
                os.remove(part)
            raise
    return count

files.archive/extract.py:
"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract checks every member before it writes anything, so an archive it refuses leaves
the destination as it was.
"""
import os
import shutil
import tarfile

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted. A link may point only inside dest, following the links
    on the way, and no member is written through a link or a file. A member that would land outside dest, a link that
    points outside it, a name listed twice, a member that would replace something already in dest, any other kind of
    member, a file that isn't a readable tar, or an archive over the size limits raises UnsafeArchive, and then nothing
    has been written."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    try:
        tar = tarfile.open(tar_path)
    except tarfile.TarError as e:
        raise UnsafeArchive(f"not a readable tar archive: {e}") from None
    with tar:
        try:
            members = tar.getmembers()
        except tarfile.TarError as e:
            raise UnsafeArchive(f"not a readable tar archive: {e}") from None
        limits.check(members)
        plan = plan_members(root, members)
        for member, target in plan:
            write_member(tar, member, target)
    return [paths.clean_name(m.name) for m in members]


def plan_members(root, members):
    """[(member, the absolute path it goes to), ...] in archive order once every member has passed, or UnsafeArchive.

    The checks run on the tree the archive will leave (its own names, plus what dest already holds), so a link is
    judged by where it actually leads, through any other link it passes, and no member is written under a link."""
    entries = {}  # clean name -> (kind, link target); kind is "dir", "file" or "link"
    order = []
    for member in members:
        name = paths.clean_name(member.name)
        if name in entries:
            raise UnsafeArchive(f"{name} is listed twice")
        if member.issym():
            entries[name] = ("link", paths.clean_link(name, member.linkname))
        elif member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        elif member.isdir():
            entries[name] = ("dir", None)
        elif member.isfile():
            entries[name] = ("file", None)
        else:
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")
        order.append((name, member))
    plan = []
    for name, member in order:
        kind, linkname = entries[name]
        check_folders_above(root, entries, name)
        target = paths.under(root, name)
        if os.path.lexists(target) and not (kind == "dir" and os.path.isdir(target) and not os.path.islink(target)):
            raise UnsafeArchive(f"{name} is already in the destination")
        if kind == "link" and reaches_outside(root, entries, name, linkname):
            raise UnsafeArchive(f"{name} links to {linkname}, outside the destination")
        plan.append((member, target))
    return plan


def check_folders_above(root, entries, name):
    """UnsafeArchive unless every folder above name is a real folder: then nothing is written through a link."""
    parts = name.split("/")
    for i in range(1, len(parts)):
        above = "/".join(parts[:i])
        kind = what_is(root, entries, above)
        if kind is not None and kind[0] != "dir":
            what = "a link" if kind[0] == "link" else "a file"
            raise UnsafeArchive(f"{name} would be written inside {above}, which is {what}, not a folder")


def what_is(root, entries, name):
    """(kind, link target) for what name will be once the archive is extracted, or None if nothing will be there."""
    if name in entries:
        return entries[name]
    path = os.path.join(root, *name.split("/"))
    if os.path.islink(path):
        return ("link", os.readlink(path))
    if os.path.isdir(path):
        return ("dir", None)
    if os.path.lexists(path):
        return ("file", None)
    return None


def reaches_outside(root, entries, name, linkname):
    """Whether the link called name, pointing at linkname, leads outside root. A target that climbs above root as a
    path is refused as it always was. Then the walk is the kernel's: the target is read from the folder the link sits
    in, every link met on the way is followed from the folder reached so far, and ".." climbs from there. A chain of
    links that loops stops at paths.MAX_HOPS, where the kernel fails with ELOOP and nothing beyond is reached, so that
    is not an escape."""
    depth = len(name.split("/")) - 1
    for part in linkname.split("/"):
        if part == "..":
            depth -= 1
            if depth < 0:
                return True
        elif part not in ("", "."):
            depth += 1
    folder = name.split("/")[:-1]  # every folder above a link is a real one, see check_folders_above
    queue = linkname.split("/")
    hops = 0
    while queue:
        part = queue.pop(0)
        if part in ("", "."):
            continue
        if part == "..":
            if not folder:
                return True
            folder.pop()
            continue
        kind = what_is(root, entries, "/".join(folder + [part]))
        if kind is not None and kind[0] == "link":
            hops += 1
            if hops > paths.MAX_HOPS:
                return False
            queue = kind[1].split("/") + queue
        else:
            folder.append(part)
    return False


def write_member(tar, member, target):
    if member.isdir():
        os.makedirs(target, exist_ok=True)
        return
    os.makedirs(os.path.dirname(target), exist_ok=True)
    if member.issym():
        os.symlink(member.linkname, target)
        return
    with tar.extractfile(member) as src, open(target, "xb") as out:
        shutil.copyfileobj(src, out)
    os.chmod(target, EXEC_MODE if member.mode & 0o100 else FILE_MODE)

