"""MANIFEST.json, written at the root of every backup: the sha256 of each file and the target of each link."""
import hashlib
import json
import os

from archive import paths
from archive.errors import UnsafeArchive
from archive.pack import walk

NAME = "MANIFEST.json"


class ManifestMismatch(ValueError):
    pass


def sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as f:
        for block in iter(lambda: f.read(1 << 16), b""):
            digest.update(block)
    return digest.hexdigest()


def build(root):
    """{"files": {path: sha256}, "links": {path: target}} for the tree under root, paths relative and POSIX."""
    files, links = {}, {}
    for rel, path in walk(root):
        if rel == NAME:
            continue
        if os.path.islink(path):
            links[rel] = os.readlink(path)
        elif os.path.isfile(path):
            files[rel] = sha256(path)
    return {"files": files, "links": links}


def dumps(manifest):
    return json.dumps(manifest, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def _path(root, rel):
    """root/rel for a path the (untrusted) manifest lists, or ManifestMismatch if it isn't a plain relative path
    that stays under root, so a manifest can't make us read or probe anything outside the restored folder."""
    try:
        clean = paths.clean_name(rel)
    except UnsafeArchive as e:
        raise ManifestMismatch(f"the manifest lists a bad path: {e}") from None
    root = os.path.realpath(root)
    path = os.path.join(root, *clean.split("/"))
    if not paths.is_within(root, os.path.realpath(os.path.dirname(path))):
        raise ManifestMismatch(f"{rel} is outside the backup")
    return path


def verify(root, manifest):
    """ManifestMismatch unless every file and link the manifest lists is under root as it says."""
    if not isinstance(manifest, dict):
        raise ManifestMismatch(f"{NAME} must hold an object")
    for rel, digest in manifest.get("files", {}).items():
        path = _path(root, rel)
        if not paths.is_within(os.path.realpath(root), os.path.realpath(path)):
            raise ManifestMismatch(f"{rel} is outside the backup")
        if os.path.islink(path) or not os.path.isfile(path):
            raise ManifestMismatch(f"{rel} is missing")
        if sha256(path) != digest:
            raise ManifestMismatch(f"{rel} doesn't match its checksum")
    for rel, target in manifest.get("links", {}).items():
        path = _path(root, rel)
        if not os.path.islink(path) or os.readlink(path) != target:
            raise ManifestMismatch(f"{rel} should link to {target}")

files.ledger/migrate_v3.py:
"""Migrate a v2 export to the v3 format.

migrate(src, accounts, dst) reads the v2 export at src (docs/FORMAT_V2.md) and the accounts file at accounts
(data/accounts.json shows the shape), writes the v3 file at dst (docs/FORMAT_V3.md, "Migrating from v2") and
returns the number of records written.

Scale: the export is streamed, never held whole. Two external sorts (sorted runs spilled to temp files, then
merged) do the work:

1. every line is converted and validated, and sorted by (id, rev, line number). Validation of the whole export
   happens here, before anything is written to dst. The line number makes the later of two lines with the same
   id and rev win, as FORMAT_V2.md says.
2. the merged stream keeps the last line of each id: the current revision.
3. the current records are sorted by (account, posted_at, id), which is the v3 order, and written out.

Memory is bounded by RUN_RECORDS records plus MERGE_WIDTH open files. Temp files go under TMPDIR (or the
system temp directory); peak use is a few times the size of the output.
"""
import decimal
import heapq
import json
import marshal
import os
import tempfile

from . import kinds, money, timefmt, v2, v3
from .accounts import load as load_accounts
from .errors import FormatError, MigrationError

RUN_RECORDS = 200_000  # records sorted in memory before a run is spilled to disk
MERGE_WIDTH = 64  # run files merged at once, so open files stay well under the OS limit


def migrate(src, accounts, dst):
    held = load_accounts(accounts)
    dst = os.fspath(dst)
    with tempfile.TemporaryDirectory(prefix="migrate_v3_") as work:
        # Phase 1 validates every line; a MigrationError here leaves dst untouched.
        runs = _sort_runs(_converted(src, held), work)
        # Phase 2 keeps the current revision of each id, and writes them in v3 order.
        current_runs = _sort_runs(_current(_merged(runs)), work)
        for path in runs:
            os.remove(path)
        return _write(current_runs, dst)


def _converted(src, held):
    """(id, rev, line, account, type, amount_minor, currency, posted_at, memo) for each non-blank line."""
    with open(src, "rb") as f:
        for number, raw in enumerate(f, 1):
            if not raw.strip():
                continue
            try:
                text = raw.decode("utf-8")
            except UnicodeDecodeError as e:
                raise MigrationError(f"not UTF-8 ({e.reason})", number) from None
            if number == 1 and text.startswith("﻿"):
                text = text[1:]  # a byte-order mark some exporters write at the start of a file
            try:
                record = json.loads(text)
            except ValueError as e:
                raise MigrationError(f"not JSON ({e})", number) from None
            try:
                v2.check(record, number)
            except FormatError as e:
                raise MigrationError(e.args[0]) from None  # the message already names the line
            yield _convert(record, number, held)


def _convert(record, number, held):
    kind = kinds.LEGACY.get(record["kind"], record["kind"])
    if kind not in kinds.TYPES:
        raise MigrationError(f"unknown kind {record['kind']!r}", number)
    account = held.get(record["account"])
    if account is None:
        raise MigrationError(f"account {record['account']!r} isn't in the accounts file", number)
    for field in ("id", "account", "memo"):
        _check_text(record[field], field, number)

    currency = account.currency if record["currency"] is None else record["currency"]
    if not money.is_currency(currency):
        raise MigrationError(f"bad currency {currency!r}", number)

    amount = record["amount"]
    try:
        # money.to_minor rounds to the context precision; widen it so no digit of the amount is lost.
        with decimal.localcontext() as ctx:
            ctx.prec = max(ctx.prec, len(amount) + 8)
            minor = money.to_minor(amount, currency)
    except ValueError as e:
        raise MigrationError(f"amount: {e}", number) from None
    if minor < 0:
        raise MigrationError(f"amount {amount} is negative; v2 amounts are positive", number)

    try:
        stamp = timefmt.parse_ts(record["ts"])
        if stamp.tzinfo is None:
            # Naive times are the account's local time (FORMAT_V2.md, "2020").
            stamp = stamp.replace(tzinfo=account.tz)
        posted_at = timefmt.to_utc_z(stamp)
    except (ValueError, OverflowError) as e:
        raise MigrationError(f"ts: {e}", number) from None

    return (record["id"], record["rev"], number, record["account"], kind,
            kinds.SIGN[kind] * minor, currency, posted_at, record["memo"])


def _check_text(value, field, number):
    try:
        value.encode("utf-8")
    except UnicodeEncodeError:
        raise MigrationError(f"{field} isn't valid Unicode text", number) from None


def _current(rows):
    """Given rows sorted by (id, rev, line), the last row of each id, rearranged as v3 order fields."""
    last = None
    for row in rows:
        if last is not None and row[0] != last[0]:
            yield _as_record(last)
        last = row
    if last is not None:
        yield _as_record(last)


def _as_record(row):
    # (account, posted_at, id, type, amount_minor, currency, memo, source_rev)
    return (row[3], row[7], row[0], row[4], row[5], row[6], row[8], row[1])


def _sort_runs(items, work):
    """Sort items (tuples, unique by their leading fields) in bounded memory. Returns sorted run file paths
    whose merge is the sorted sequence."""
    runs, batch = [], []
    for item in items:
        batch.append(item)
        if len(batch) >= RUN_RECORDS:
            runs.append(_spill(batch, work))
            batch = []
    if batch:
        runs.append(_spill(batch, work))
    return _reduce(runs, work)


def _spill(batch, work):
    batch.sort()
    path = _new_path(work)
    with open(path, "wb") as f:
        for item in batch:
            marshal.dump(item, f)
    batch.clear()
    return path


def _reduce(runs, work):
    """Merge runs in groups of MERGE_WIDTH until few enough remain to merge in one pass."""
    while len(runs) > MERGE_WIDTH:
        merged = []
        for i in range(0, len(runs), MERGE_WIDTH):
            group = runs[i:i + MERGE_WIDTH]
            path = _new_path(work)
            with open(path, "wb") as f:
                for item in _merged(group):
                    marshal.dump(item, f)
            for old in group:
                os.remove(old)
            merged.append(path)
        runs = merged
    return runs


def _merged(paths):
    return heapq.merge(*(_read_run(path) for path in paths))


def _read_run(path):
    with open(path, "rb") as f:
        while True:
            try:
                item = marshal.load(f)
            except EOFError:
                return
            yield item


def _new_path(work):
    fd, path = tempfile.mkstemp(dir=work, suffix=".run")
    os.close(fd)
    return path


def _write(runs, dst):
    """Stream the sorted records to dst through a partial file, so a failed write leaves no half-written dst."""
    partial = dst + ".partial"
    count = 0
    try:
        with open(partial, "w", encoding="utf-8", newline="\n") as f:
            for item in _merged(runs):
                f.write(v3.dump_line(_to_v3(item)))
                count += 1
        os.replace(partial, dst)
    except BaseException:
        try:
            os.remove(partial)
        except FileNotFoundError:
            pass
        raise
    return count


def _to_v3(item):
    account, posted_at, record_id, kind, amount_minor, currency, memo, source_rev = item
    return {"account": account, "amount_minor": amount_minor, "currency": currency, "id": record_id,
            "memo": memo, "posted_at": posted_at, "source_rev": source_rev, "type": kind}

