"""Ranking totals. Equal totals share a rank and the next rank skips past them, so 1, 2, 2, 4."""


def competition_ranks(totals):
    """[(rank, total), ...] by cents, biggest first. Totals that share a rank keep the order they came in."""
    # A total's rank is 1 + how many totals have strictly more cents. Count those once per distinct amount.
    above, rank_of = 0, {}
    amounts = {}
    for total in totals:
        amounts[total.cents] = amounts.get(total.cents, 0) + 1
    for cents in sorted(amounts, reverse=True):
        rank_of[cents] = 1 + above
        above += amounts[cents]
    ranked = [(rank_of[total.cents], total) for total in totals]
    ranked.sort(key=lambda pair: pair[0])
    return ranked


def top(totals, places):
    """The ranked totals placed in the first `places` ranks, with every total tied for the last of them."""
    return [(rank, total) for rank, total in competition_ranks(totals) if rank <= places]

files.archive/extract.py:
"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract works out where every member will land before it writes anything. It keeps a model
of the destination's tree, applies the members to that model in archive order, and resolves each path the way the
system does, following links, including links that an earlier member of the same archive adds. Only then does it
write, and only to the resolved paths, which never pass through a link. An archive it refuses leaves the destination
as it was.
"""
import os
import shutil
import tarfile

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755
MAX_HOPS = 40  # links followed by one walk before it counts as a loop, the same limit the kernel uses

DIR = ("dir",)
FILE = ("file",)  # anything in the tree that isn't a folder or a link
# A link is ("link", target). The tree maps each path under the destination, as a tuple of names with no link in it,
# to one of these.


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted, and a link may point only inside dest, whether it points
    at a path directly or through other links. A member that would land outside dest, a link that points outside it,
    a name listed twice, any other kind of member, an archive over the size limits, or a member that clashes with
    what is already in dest raises UnsafeArchive, and then nothing has been written."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    with tarfile.open(tar_path) as tar:
        members = tar.getmembers()
        limits.check(members)
        plan = plan_members(root, members)
        for member, target in plan:
            write_member(tar, member, target)
    return [paths.clean_name(m.name) for m in members]


def plan_members(root, members):
    """[(member, the absolute path it is written to), ...] once every member has passed, or UnsafeArchive.

    Nothing is written here. The tree is modelled, starting from what is already in root, and each member is applied
    to the model in archive order, as write_member will apply it. Once every member is in, each link in the final
    tree is followed to the end, so a link that points through a link added later is caught too."""
    state = _existing(root)
    seen = set()
    plan = []
    for member in members:
        name = paths.clean_name(member.name)
        if name in seen:
            raise UnsafeArchive(f"{name} is listed twice")
        seen.add(name)
        if member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        if not (member.isdir() or member.isfile() or member.issym()):
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")
        parts = tuple(name.split("/"))
        if member.isdir():
            real = _resolve(state, (), parts, create=True)
            if state.get(real) == FILE:
                raise UnsafeArchive(f"{name} is a file in the destination")
            plan.append((member, _path(root, real)))
            continue
        parent = _resolve(state, (), parts[:-1], create=True)
        if state.get(parent) == FILE:
            raise UnsafeArchive(f"{name} would be written inside a file")
        real = parent + (parts[-1],)
        if real in state:
            raise UnsafeArchive(f"{name} is already in the destination")
        if member.issym():
            _target_parts(member.linkname)
            state[real] = ("link", member.linkname)
        else:
            state[real] = FILE
        plan.append((member, _path(root, real)))
    for real, node in state.items():
        if node[0] == "link":
            try:
                _resolve(state, real[:-1], _target_parts(node[1]), create=False)
            except UnsafeArchive as e:
                raise UnsafeArchive(f"{'/'.join(real)} links to {node[1]}: {e}") from None
    return plan


def write_member(tar, member, target):
    if member.isdir():
        os.makedirs(target, exist_ok=True)
        return
    os.makedirs(os.path.dirname(target), exist_ok=True)
    if member.issym():
        os.symlink(member.linkname, target)
        return
    with tar.extractfile(member) as src, open(target, "xb") as out:
        shutil.copyfileobj(src, out)
    os.chmod(target, EXEC_MODE if member.mode & 0o100 else FILE_MODE)


def _raise(error):
    raise error


def _existing(root):
    """The tree as it is in root before anything is extracted, in the same form plan_members builds. Links are
    recorded as links and not followed, the way os.walk leaves them alone."""
    state = {}
    for here, dirs, files in os.walk(root, onerror=_raise):
        for name in dirs + files:
            path = os.path.join(here, name)
            key = tuple(os.path.relpath(path, root).split(os.sep))
            if os.path.islink(path):
                state[key] = ("link", os.readlink(path))
            elif os.path.isdir(path):
                state[key] = DIR
            else:
                state[key] = FILE
    return state


def _target_parts(target):
    if not target or "\x00" in target or target.startswith("/"):
        raise UnsafeArchive("the target is empty, absolute or holds a NUL")
    return target.split("/")


def _resolve(state, start, parts, create):
    """The path, as a tuple of names under the root, that the system reaches by walking parts from the folder start,
    following every link on the way. With create, a missing folder is made as os.makedirs makes it, but never through
    a link, which os.makedirs can't do either. Without it, a missing name is left alone, and nothing below it counts.
    UnsafeArchive if the walk climbs out of the root, goes through a file, loops, or runs into a missing folder
    through a link or past a missing folder."""
    real = tuple(start)
    hops = 0
    missing = False
    pending = [(part, False) for part in reversed(parts)]  # (name, reached through a link)
    while pending:
        part, through_link = pending.pop()
        if part in ("", "."):
            continue
        if part == "..":
            if missing:
                raise UnsafeArchive("it climbs up from a folder that isn't there")
            if not real:
                raise UnsafeArchive("it climbs out of the destination")
            real = real[:-1]
            continue
        here = real + (part,)
        node = state.get(here)
        if node is None:
            if not create:
                missing = True
            elif through_link:
                raise UnsafeArchive("it goes through a link to a folder that isn't there")
            else:
                state[here] = DIR
            real = here
        elif node[0] == "link":
            hops += 1
            if hops > MAX_HOPS:
                raise UnsafeArchive("the links loop")
            pending.extend((p, True) for p in reversed(_target_parts(node[1])))
        else:
            real = here
            if node == FILE and any(p not in ("", ".") for p, _ in pending):
                raise UnsafeArchive("it goes through a file")
    return real


def _path(root, real):
    return os.path.join(root, *real)

